        'we need to fill PIO_CUS_ECON daily as all reports depends on it',
        'Based on our web session kindly find below the status:      • Issue Reported by the customer: empty data.    • Status: Solved.    • Problem description: View BI_DWH.PIO_CUS_ECON did not hold the data for more than (5) days because the delete retention which keeps (5) days on the BI_ODS level run on the table BI_ODS.CUS_ECON, so the data keeps removed.    • Action Taken—recommended solution: Based on our web session, the issue was resolved after I excluded table BI_ODS.CUS_ECON from the delete retention.',
