(
        '17824',
        'CMS Not Running on ETL & SAP BO application servers',
        'Dear Team,    We urgently need support to resolve the issue of being unable to login into both SAP BO & Data Services applications. Business reports are currently unavailable.',
        'Dears    Based on our sessions , kindly find below summary regarding the issues we faced:    Issues:  - SAP BI and SAP IPS CMS.exe failed to start many times.  - SAP BI and SAP IPS server intelligence agent services is up and running but unable to start up the DB CMS.  - SAP DS tools like designer and DS management console didn’t work.    Status:  - All issues resolved.    Causes:    - optimizer_adaptive_features was enabled on oracle DB.  - bug in Oracle 12c relating to new optimizer features.  - optimizer_adaptive_features corrupt SAP BI and SAP IPS cluster keys .    Actions and solutions:    - Reference to SAP Note optimizer_adaptive_features has a bug that prevent SAP BI and SAP IPS CMS from starting.  - optimizer_adaptive_features value changed to False.   - Renew the SAP BI and SAP IPS cluster key.    Recommendation:    - Disable optimizer_adaptive_features by setting optimizer_adaptive_features=false  - As second action if previous step didn’t work ,Set optimizer_dynamic_sampling=0 and set cursor_sharing from EXACT to FORCE.  - Please discuss this step with DBA carefully as the change may cause other unexpected issues.  - Keep a backup for SAP repositories separately as a dump user.  - Keep a backup for file store on an external drive.  - Keep a backup for SAP BI objects like (reports, universes, groups,…etc) as a LCMBIAR files using SAP BI promotion management wizard , I can provide you with a steps and show you how to.  - Keep a backup for SAP Data service workflows.  - Upgrade the DB to Oracle 19C. (will be implemented once the upgrade project is done)  - Upgrade SAP products to the latest versions and patches. (will be implemented once the upgrade project is done).',
        '2025-01-12T00:00:00.000Z'::timestamptz,
        '2025-01-13T00:00:00.000Z'::timestamptz,
        '015a7170-65d3-490b-bd00-2c41faabf8f9'::uuid,
