        'Based on our web session kindly find below the status:      • Issue Reported by the customer: Fill missing dates.    • Status: Solved.    • Problem description: The data extraction was not filled for the dates between (15/01/2025) and (02/02/2025) because of the following:    1- The core database password was changed from the bank side, noting that changing the core password must also reflect on the ETL.  2- The core EOD process has not closed since (15/01/2025) therefore there were no transactions on these missing dates.     • Action Taken – recommended solution: Kindly note that the issue was resolved after filling in the missing dates, please consider the following:  1- Changing the database passwords may cause the ETL job to fail or not extract the data correctly, for the next time kindly inform us in order not to miss any data extraction.  2- There is a delay from the bank side in closing the EOD process, which affects the daily data extraction on the data warehouse and causes the AML engine to not work properly.',
        '2025-01-27T00:00:00.000Z'::timestamptz,
