        'Check BI report',
        'There are many records that do not appear in a report at different times, old contracts and new contracts until yesterday''s date',
        'Based on our web session kindly find below the status:      • Issue Reported by the customer: Missing records.    • Status: Solved.    • Problem description: There are many records that do not appear in a report at different times, old contracts and new contracts until yesterday''s date .    • Action Taken – recommended solution: The issue was related to missing records in the report for both old and new contracts. Upon investigation, it was found that the missing data was not existing in the CORE Database. I traced the PROCEDURE DWH and ODS, but the required data was not available. After reviewing the joins and Based on your request, I implemented an OUTER JOIN between PIO_CUSTOMER and PIO_ACCT_MGR to ensure all relevant records, including those that were missing, appeared in the report.',
