(
        '18059',
        'Duplicate account manager name data issue',
        'Dear Support Team,    Please be informed that we have a recurring issue on ETL process which prevent data transformation job from completing successfully.    The issue that the ETL is looking on ACCT_MGR and MGR_NAME columns as a primary key, and since MGR_NAME is inserting manually each time on BANKS side, its very default to prevent this issue from coming up again (sometimes space issue).    To resolve this issue, we propose modifying ETL process, to read data from BANKS side based on ACCT_MGR and BRA_CODE (and maybe tell_id) as a primary key instead on the current approach.    Please check the attached excel sheet for more details, and let me know if meeting needed to discuss this further.',
        'Based on our web session kindly find below the status:      • Issue Reported by the customer: Duplicate account manager name data issue.    • Status: Solved.    • Problem description: The ETL daily fill keeps failing due to a duplicate on the ACCT_MGR table.    • Action Taken – recommended solution: Based on our web session, kindly be informed that the issue was resolved by modifying the table primary key on the ETL to be ACCT_MGR and BRA_CODE instead of ACCT_MGR and MGR_NAME.',
