        'Issue on CRIF',
        'Dear Pio-Tech Team,    Hope you are doing well.  We are facing an issue on the CRIF where three accounts are not appearing    101975 ?????? ????     40593 ?????? ?????     58538 ?????? ?????     Kindly investigate and provide your feedback on this issue at your earliest convenience.',
        'Dear Mohammad,    Please find below my comments regarding your notes        We are facing an issue on the CRIF where three accounts are not appearing    101975 ?????? ????   Pio tech comment: Closed accounts should not be included in the CRIF report, and as such, we have excluded them.    40593 ?????? ?????   Pio tech comment: As per CRIF requirements, the customer profile reports include only the original customers, not joint accounts. Consequently, joint accounts will not appear in the report. Please refer to the original customers linked to the joint accounts for verification.    58538 ?????? ?????     Pio tech comment: As per CRIF requirements, the customer profile reports include only the original customers, not joint accounts. Consequently, joint accounts will not appear in the report. Please refer to the original customers linked to the joint accounts for verification.',
