        '18159',
        'Issue on manual screen',
        'Dear Pio-Tech Support,  Please note that the data lists have not been updating as expected.   Kindly asking your support in resolving this issue  Additionally, we have noticed an issue when searching for full names. When entering the complete name, the expected result does not appear; however, when searching using only first name, the expected result is displayed.   For example, searching for "Karim Asad Ahmad Khan" doesn’t return the expected result, but searching for "Karim Asad Ahmad" does. Please refer to the attached image for further clarification.  Best,',
        'Dear Hanan,  Please be informed that there is no issue with the manual screen. The example you provided contains multiple nicknames and consists of three layers: "Karim Asad Ahmad". When you search using the last name, which is the fourth layer ("Khan"), the score percentage will be lower than what you see in the interface.  This is because our algorithm prioritizes nicknames rather than the full name ("Karim Asad Ahmad Khan") during the search process.  Let me know if you need further clarification.',
